import{_ as t,o as d,c as o,a2 as i}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Sprite Themes, 5-State Variants & Base Renderer","description":"","frontmatter":{},"headers":[],"relativePath":"en/1.21.1/ui/index.md","filePath":"en/1.21.1/ui/index.md"}'),a={name:"en/1.21.1/ui/index.md"};function s(r,e,n,c,l,p){return d(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="sprite-themes-5-state-variants-base-renderer" tabindex="-1">Sprite Themes, 5-State Variants &amp; Base Renderer <a class="header-anchor" href="#sprite-themes-5-state-variants-base-renderer" aria-label="Permalink to &quot;Sprite Themes, 5-State Variants &amp; Base Renderer&quot;">​</a></h1><p><code>module.ui</code> (Mod ID: <code>anvillib_ui</code>) provides a lightweight <strong>client-side flexible widget rendering library (<code>dev.anvilcraft.lib.v2.ui.flexible</code>)</strong> for NeoForge 1.21.1. Using a nine-slice sprite lookup table (<code>FlexibleSprites</code>) and a <strong>configured <code>Renderer</code> + per-frame <code>Scope</code></strong> separation model, it effortlessly draws auto-sizing 3D/flat buttons, dual-theme toggles, and pointer flyouts.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h3 id="gradle-repositories-dependencies" tabindex="-1">Gradle Repositories &amp; Dependencies <a class="header-anchor" href="#gradle-repositories-dependencies" aria-label="Permalink to &quot;Gradle Repositories &amp; Dependencies&quot;">​</a></h3><p>Official releases are available on Maven Central, but <code>Cjsah Maven</code> with <code>exclusiveContent</code> filtering is recommended to avoid NeoForge Maven&#39;s incomplete Maven Central sync causing interface injection or transitive metadata errors:</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">repositories</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    exclusiveContent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        forRepository</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">            maven</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://server.cjsah.net:1002/maven/releases&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Cjsah Maven&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">            includeGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dev.anvilcraft.lib&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    mavenCentral</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    implementation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dev.anvilcraft.lib:anvillib-neoforge-1.21.1:${anvillib_version}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="entry-client-restrictions" tabindex="-1">Entry &amp; Client Restrictions <a class="header-anchor" href="#entry-client-restrictions" aria-label="Permalink to &quot;Entry &amp; Client Restrictions&quot;">​</a></h3><ul><li><strong><code>AnvilLibUi</code></strong>: Marked <code>@Mod(value = AnvilLibUi.MOD_ID, dist = Dist.CLIENT)</code> (<code>MOD_ID = &quot;anvillib_ui&quot;</code>), providing <code>AnvilLibUi.of(String path)</code> for <code>anvillib_ui:&lt;path&gt;</code> resource locations.</li><li>All classes in this module belong to the client rendering domain and may only be used on <code>Dist.CLIENT</code> render paths.</li></ul><h2 id="design-philosophy-4d-sprite-lookup-scope-lifecycle" tabindex="-1">Design Philosophy: 4D Sprite Lookup &amp; Scope Lifecycle <a class="header-anchor" href="#design-philosophy-4d-sprite-lookup-scope-lifecycle" aria-label="Permalink to &quot;Design Philosophy: 4D Sprite Lookup &amp; Scope Lifecycle&quot;">​</a></h2><h3 id="_1-4d-addressing-of-nine-slice-sprites" tabindex="-1">1. 4D Addressing of Nine-Slice Sprites <a class="header-anchor" href="#_1-4d-addressing-of-nine-slice-sprites" aria-label="Permalink to &quot;1. 4D Addressing of Nine-Slice Sprites&quot;">​</a></h3><p>All built-in flexible widget sprite paths follow <code>anvillib_ui:flex_button/&lt;theme&gt;&lt;style&gt;&lt;type&gt;&lt;variant&gt;</code>, uniquely determined by 4 orthogonal enums:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Enum</th><th>Values &amp; Path Segments (<code>getPath()</code>)</th><th>Design Semantics</th></tr></thead><tbody><tr><td><strong>Theme</strong></td><td><code>SpriteTheme</code></td><td><code>LIGHT</code> (<code>&quot;&quot;</code>), <code>DARK</code> (<code>&quot;dark&quot;</code>)</td><td>Light/dark panel color scheme</td></tr><tr><td><strong>Style</strong></td><td><code>SpriteStyle</code></td><td><code>THREE_D</code> (<code>&quot;&quot;</code>), <code>FLAT</code> (<code>&quot;flat&quot;</code>)</td><td>Raised bevel border / flat style</td></tr><tr><td><strong>Shadow</strong></td><td><code>SpriteType</code></td><td><code>NON_SHADED</code>, <code>SHADED_1PX</code>, <code>SHADED_2PX</code></td><td>Controls bottom shadow pixels; pressed states shift bottom shadow to top padding for a &quot;depressed&quot; look</td></tr><tr><td><strong>Variant</strong></td><td><code>SpriteVariant</code></td><td><code>NORMAL</code> (<code>&quot;&quot;</code>), <code>HIGHLIGHTED</code>, <code>PRESSED</code>, <code>HIGHLIGHTED_PRESSED</code>, <code>HIGHLIGHTED_PRESSING</code></td><td>Normal, hovered, selected, selected+hovered, hovered+pressing</td></tr></tbody></table><p><code>FlexibleSprites</code> precomputes nine-slice paddings (<code>left/top/right/bottomPadding</code>) and upward pointer inset (<code>pointerUpInset = max(0, topPadding - 2)</code>) for all 4D combinations at class init with zero per-frame allocation.</p><h3 id="_2-lifecycle-separation-between-renderer-and-scope" tabindex="-1">2. Lifecycle Separation Between <code>Renderer</code> and <code>Scope</code> <a class="header-anchor" href="#_2-lifecycle-separation-between-renderer-and-scope" aria-label="Permalink to &quot;2. Lifecycle Separation Between `Renderer` and `Scope`&quot;">​</a></h3><ul><li><strong><code>Renderer&lt;T extends Scope&gt;</code></strong> (long-lived): holds widget appearance settings (theme, style, type, button mode, <code>BooleanSupplier</code> toggle state, press start pos, and current <code>alpha</code>), reusable across frames as a <code>Screen</code> field.</li><li><strong><code>Renderer.Scope</code></strong> (per-frame short-lived, implements <code>AutoCloseable</code>): binds per-draw dynamic context (<code>GuiGraphics</code>, <code>pos</code>, <code>size</code> / <code>flexSize</code>, <code>mousePos</code>, <code>font</code>, <code>text</code>, <code>textOffset</code>). <ul><li><strong>Recommended pattern</strong>: <code>try (var scope = renderer.open()) { ... scope.render(); }</code> each frame. Exiting clears references to <code>graphics</code>, <code>font</code>, <code>text</code>, etc. to prevent leaks.</li><li><strong>Press/hit-test cycle guard</strong>: <code>flexSize(...)</code> generates separate variant-bound draw <code>size</code> and fixed-<code>NORMAL</code> <code>hitSize</code> functions, preventing infinite recursion when <code>basedOnMouse</code> calls <code>contains</code> -&gt; <code>size</code> -&gt; variant. Consequently, shaded buttons depress visually by 1px while keeping <code>NORMAL</code> hit-test height for anti-flicker stability.</li></ul></li></ul><h2 id="full-public-api-reference" tabindex="-1">Full Public API Reference <a class="header-anchor" href="#full-public-api-reference" aria-label="Permalink to &quot;Full Public API Reference&quot;">​</a></h2><h3 id="_1-anvillibui" tabindex="-1">1. <code>AnvilLibUi</code> <a class="header-anchor" href="#_1-anvillibui" aria-label="Permalink to &quot;1. `AnvilLibUi`&quot;">​</a></h3><p>Package: <code>dev.anvilcraft.lib.v2.ui</code></p><table tabindex="0"><thead><tr><th>Member Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>public static final String MOD_ID = &quot;anvillib_ui&quot;</code></td><td>Module Mod ID</td></tr><tr><td><code>static ResourceLocation of(String path)</code></td><td>Creates <code>anvillib_ui:&lt;path&gt;</code> resource location</td></tr></tbody></table><h3 id="_2-core-enums-flexiblesprites" tabindex="-1">2. Core Enums &amp; <code>FlexibleSprites</code> <a class="header-anchor" href="#_2-core-enums-flexiblesprites" aria-label="Permalink to &quot;2. Core Enums &amp; `FlexibleSprites`&quot;">​</a></h3><p>Package: <code>dev.anvilcraft.lib.v2.ui.flexible</code></p><table tabindex="0"><thead><tr><th>Type / Method Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>enum SpriteTheme</code> (<code>LIGHT</code>, <code>DARK</code>)</td><td>Provides <code>getPath()</code> (<code>&quot;&quot;</code> / <code>&quot;dark&quot;</code>)</td></tr><tr><td><code>enum SpriteStyle</code> (<code>THREE_D</code>, <code>FLAT</code>)</td><td>Provides <code>getPath()</code> (<code>&quot;&quot;</code> / <code>&quot;flat&quot;</code>)</td></tr><tr><td><code>enum SpriteType</code> (<code>NON_SHADED</code>, <code>SHADED_1PX</code>, <code>SHADED_2PX</code>)</td><td>Provides <code>getPath()</code> (<code>&quot;non_shaded&quot;</code> / <code>&quot;shaded_1px&quot;</code> / <code>&quot;shaded_2px&quot;</code>)</td></tr><tr><td><code>enum SpriteVariant</code> (<code>NORMAL</code>, <code>HIGHLIGHTED</code>, <code>PRESSED</code>, <code>HIGHLIGHTED_PRESSED</code>, <code>HIGHLIGHTED_PRESSING</code>)</td><td>Provides <code>getPath()</code></td></tr><tr><td><code>enum PointerDirection</code> (<code>LEFT</code>, <code>RIGHT</code>, <code>UP</code>, <code>DOWN</code>)</td><td>Provides <code>getPath()</code> (<code>&quot;left&quot;</code> / <code>&quot;right&quot;</code> / <code>&quot;up&quot;</code> / <code>&quot;down&quot;</code>)</td></tr><tr><td><code>static SpriteInfo FlexibleSprites.pickSprite(SpriteTheme, SpriteStyle, SpriteType, SpriteVariant)</code></td><td>Returns the exact matching body sprite and padding <code>SpriteInfo</code></td></tr><tr><td><code>static @Nullable PointerSprite FlexibleSprites.pickPointer(SpriteTheme, SpriteStyle, SpriteType, SpriteVariant, PointerDirection)</code></td><td>Loads and caches <code>textures/gui/pointer/...png</code> visible dimensions (trimming <code>1px</code> transparent margin on all 4 sides); returns <code>null</code> if that variant texture is absent</td></tr><tr><td><code>record SpriteInfo(ResourceLocation sprite, int leftPadding, int topPadding, int rightPadding, int bottomPadding, int pointerUpInset)</code></td><td>Also provides a 5-arg compat constructor (defaulting <code>pointerUpInset = 0</code>)</td></tr><tr><td><code>record PointerSprite(ResourceLocation texture, int width, int height, int pointerUpInset)</code></td><td>Pointer texture path and visible pixel dimensions</td></tr></tbody></table><h3 id="_3-renderer-t-extends-renderer-t-scope-renderer-scope" tabindex="-1">3. <code>Renderer&lt;T extends Renderer&lt;T&gt;.Scope&gt;</code> &amp; <code>Renderer.Scope</code> <a class="header-anchor" href="#_3-renderer-t-extends-renderer-t-scope-renderer-scope" aria-label="Permalink to &quot;3. `Renderer&lt;T extends Renderer&lt;T&gt;.Scope&gt;` &amp; `Renderer.Scope`&quot;">​</a></h3><p>Package: <code>dev.anvilcraft.lib.v2.ui.flexible</code></p><h4 id="renderer-t-appearance-interaction-configuration-methods" tabindex="-1"><code>Renderer&lt;T&gt;</code> Appearance &amp; Interaction Configuration Methods <a class="header-anchor" href="#renderer-t-appearance-interaction-configuration-methods" aria-label="Permalink to &quot;`Renderer&lt;T&gt;` Appearance &amp; Interaction Configuration Methods&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Method Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>getTheme()</code> / <code>getStyle()</code> / <code>getType()</code> / <code>getAlpha()</code></td><td>Lombok <code>@Getter</code> property accessors</td></tr><tr><td><code>Renderer&lt;T&gt; dark()</code></td><td>Switches to dark theme <code>SpriteTheme.DARK</code></td></tr><tr><td><code>Renderer&lt;T&gt; flat()</code></td><td>Switches to flat style <code>SpriteStyle.FLAT</code></td></tr><tr><td><code>Renderer&lt;T&gt; shaded1px()</code> / <code>shaded2px()</code></td><td>Switches to <code>SHADED_1PX</code> / <code>SHADED_2PX</code> shadow type</td></tr><tr><td><code>Renderer&lt;T&gt; highlighted()</code> / <code>pressed()</code> / <code>highlightedPressed()</code> / <code>highlightedPressing()</code></td><td>Locks this renderer to a static variant (overriding mouse derivation)</td></tr><tr><td><code>Renderer&lt;T&gt; buttonType(ButtonType buttonType)</code></td><td>Sets button interaction mode (default <code>ButtonType.DISPLAY</code>)</td></tr><tr><td><code>Renderer&lt;T&gt; toggleState(BooleanSupplier toggleState)</code></td><td>Binds selected-state supplier for <code>ButtonType.TOGGLE</code> (default <code>() -&gt; false</code>)</td></tr><tr><td><code>Renderer&lt;T&gt; alpha(float alpha)</code></td><td>Sets overall opacity clamped to <code>[0.0F, 1.0F]</code>; ignores <code>NaN</code> to prevent fade flicker</td></tr><tr><td><code>Renderer&lt;T&gt; basedOnMouse()</code></td><td>Enables mouse-adaptive interaction (allows left and right click press feedback)</td></tr><tr><td><code>Renderer&lt;T&gt; basedOnMouse(IntSet allowedKeys)</code></td><td>Enables mouse-adaptive interaction with custom allowed GLFW mouse button codes</td></tr><tr><td><code>void onPress(int x, int y)</code> / <code>onPress(Vector2f pos)</code></td><td>Called in <code>Screen#mouseClicked</code> to record press start coordinates</td></tr><tr><td><code>void onRelease()</code></td><td>Called in <code>Screen#mouseReleased</code> to clear press start coordinates</td></tr><tr><td><code>SpriteVariant variantOf(T scope)</code></td><td>Evaluates the <code>SpriteVariant</code> for <code>scope</code> without drawing</td></tr><tr><td><code>abstract T open()</code></td><td>Opens a single-frame draw scope</td></tr></tbody></table><h4 id="renderer-scope-fluent-config-draw-methods-implements-autocloseable" tabindex="-1"><code>Renderer.Scope</code> Fluent Config &amp; Draw Methods (<code>implements AutoCloseable</code>) <a class="header-anchor" href="#renderer-scope-fluent-config-draw-methods-implements-autocloseable" aria-label="Permalink to &quot;`Renderer.Scope` Fluent Config &amp; Draw Methods (`implements AutoCloseable`)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Method Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>Scope graphics(GuiGraphics graphics)</code></td><td>Binds this frame&#39;s <code>GuiGraphics</code> (required)</td></tr><tr><td><code>Scope font(Font font)</code></td><td>Binds the <code>Font</code> used for text drawing and <code>flexSize</code> calculation</td></tr><tr><td><code>Scope pos(int x, int y)</code> / <code>pos(Vector2i pos)</code></td><td>Sets top-left pixel coordinates (required)</td></tr><tr><td><code>Scope mousePos(int x, int y)</code> / <code>mousePos(Vector2f pos)</code></td><td>Binds this frame&#39;s mouse coordinates (required when <code>basedOnMouse</code> and not <code>DISPLAY</code>)</td></tr><tr><td><code>Scope size(int width, int height)</code> / <code>size(Vector2i size)</code></td><td>Manually sets fixed rectangle dimensions (mutually exclusive with <code>flexSize</code>; one is required)</td></tr><tr><td><code>Scope flexSize(int padding)</code> / <code>(horizontalPadding, verticalPadding)</code> / <code>(left, top, right, bottom)</code></td><td>Auto-computes dimensions from <code>font</code> + <code>text</code> size, extra padding, and sprite border thickness, and sets <code>textOffset</code> automatically</td></tr><tr><td><code>Scope literal(String)</code> / <code>translatable(...)</code> / <code>translatableWithFallback(...)</code> / <code>text(Component)</code></td><td>Sets the text component for drawing and measurement</td></tr><tr><td><code>Scope textOffset(int x, int y)</code> / <code>textOffset(Vector2i)</code></td><td>Manually sets extra text offset inside top-left padding (call <strong>after</strong> <code>flexSize</code>, since <code>flexSize</code> overwrites it)</td></tr><tr><td><code>@Nullable Vector2i resolveSize()</code></td><td>Returns resolved render dimensions, or <code>null</code> if neither <code>size</code> nor <code>flexSize</code> was called</td></tr><tr><td><code>boolean contains(@Nullable Vector2f point)</code></td><td>Checks whether <code>point</code> falls inside this widget&#39;s hit box (using <code>hitSize</code>)</td></tr><tr><td><code>Scope render()</code></td><td>Validates all required fields (throws <code>IllegalStateException</code> if missing), executes subclass draw, and returns <code>this</code></td></tr><tr><td><code>void close()</code></td><td>Clears frame-held references and releases the scope</td></tr></tbody></table>',28)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
